import math
def cos(a, b):
    dot = sum(x*y for x, y in zip(a, b))
    na, nb = math.sqrt(sum(x*x for x in a)), math.sqrt(sum(x*x for x in b))
    return dot / (na * nb)
items = {"img1": [0.9, 0.1, 0.2], "aud1": [0.2, 0.9, 0.1], "txt1": [0.8, 0.2, 0.3]}
query = [0.85, 0.15, 0.25]
for name, vec in sorted(items.items(), key=lambda kv: -cos(query, kv[1])):
    print("%s similarity=%.3f" % (name, cos(query, vec)))

