import math
def cos(a, b):
    d = sum(x*y for x, y in zip(a, b))
    return d / (math.sqrt(sum(x*x for x in a)) * math.sqrt(sum(x*x for x in b)) + 1e-9)
gallery = {"bridge.jpg": [0.9, 0.05, 0.3], "cat.jpg": [0.05, 0.9, 0.2]}
text_q = [0.85, 0.1, 0.28]
best = max(gallery, key=lambda k: cos(text_q, gallery[k]))
print("text query matched image:", best)

