text_scores = {"d1": 0.9, "d2": 0.4, "d3": 0.6}
img_scores = {"d1": 0.5, "d2": 0.8, "d4": 0.7}
def norm(s):
    lo, hi = min(s.values()), max(s.values())
    return {k: (v - lo) / (hi - lo + 1e-9) for k, v in s.items()}
nt, ni = norm(text_scores), norm(img_scores)
fused = {}
for d in set(nt) | set(ni):
    fused[d] = 0.6 * nt.get(d, 0) + 0.4 * ni.get(d, 0)
for d, s in sorted(fused.items(), key=lambda kv: -kv[1]):
    print("%s fused=%.3f" % (d, s))

