def ahash(grid):
    flat = [p for row in grid for p in row]
    mean = sum(flat) / len(flat)
    return sum(1 << i for i, p in enumerate(flat) if p > mean)
def ham(a, b): return bin(a ^ b).count("1")
g1 = [[i + j for j in range(8)] for i in range(8)]
g2 = [[i + j + (1 if (i, j) == (3, 3) else 0) for j in range(8)] for i in range(8)]
g3 = [[64 - i - j for j in range(8)] for i in range(8)]
h1, h2, h3 = ahash(g1), ahash(g2), ahash(g3)
print("near-dupe:", ham(h1, h2), "bits | different:", ham(h1, h3), "bits")

